//! Parity with ES 9.5.5's H3 library: fixtures generated by its own jar
//! (`elasticsearch-h3-9.5.5.jar`, see `fixtures/Gen.java`) on points chosen
//! where approximate trigonometry matters (cell vertices and edge midpoints
//! and points a ulp off them, around pentagons, at the poles and the
//! dateline) plus random ones, and on cells of every resolution.

use super::*;

fn gunzip(bytes: &[u8]) -> String {
    use std::io::Read;
    let mut s = String::new();
    flate2::read::GzDecoder::new(bytes).read_to_string(&mut s).unwrap();
    s
}

fn f(hex: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(hex, 16).unwrap())
}

fn h(hex: &str) -> u64 {
    u64::from_str_radix(hex, 16).unwrap()
}

/// Every point's cell at every resolution equals ES's.
#[test]
fn geo_to_h3_matches_es() {
    let text = gunzip(include_bytes!("fixtures/points.txt.gz"));
    let mut n = 0;
    let mut bad = Vec::new();
    for line in text.lines() {
        let v: Vec<&str> = line.split(' ').collect();
        let (lat, lon) = (f(v[0]), f(v[1]));
        for (res, want) in v[2..].iter().enumerate() {
            n += 1;
            let got = geo_to_h3(lat, lon, res as i32).unwrap();
            if got != h(want) {
                bad.push(format!("({lat:?}, {lon:?}) res {res}: {} != {want}", to_string(got)));
            }
        }
    }
    assert!(n > 40_000, "{n}");
    assert!(bad.is_empty(), "{} of {n} differ, e.g. {:?}", bad.len(), &bad[..bad.len().min(10)]);
}

/// Every cell's centre, boundary (to the bit), parent, children,
/// non-intersecting children and ring equal ES's.
#[test]
fn cells_match_es() {
    let text = gunzip(include_bytes!("fixtures/cells.txt.gz"));
    let mut n = 0;
    for line in text.lines() {
        let p: Vec<&str> = line.split('|').collect();
        let c = h(p[0]);
        assert!(is_valid(c), "{line}");
        let ctr: Vec<f64> = p[1].split(' ').map(f).collect();
        let got = to_lat_lng(c);
        assert_eq!((got.lat.to_bits(), got.lon.to_bits()), (ctr[0].to_bits(), ctr[1].to_bits()), "centre of {}", p[0]);
        let want: Vec<f64> = p[2].split(' ').map(f).collect();
        let got: Vec<f64> = boundary(c).iter().flat_map(|l| [l.lat, l.lon]).collect();
        assert_eq!(got.iter().map(|x| x.to_bits()).collect::<Vec<_>>(), want.iter().map(|x| x.to_bits()).collect::<Vec<_>>(), "boundary of {}", p[0]);
        assert_eq!(parent(c).map(to_string).unwrap_or_else(|| "-".into()), p[3], "parent of {}", p[0]);
        if p[4] != "-" {
            assert_eq!(children(c).into_iter().map(to_string).collect::<Vec<_>>().join(" "), p[4], "children of {}", p[0]);
            assert_eq!(no_children_intersecting(c).into_iter().map(to_string).collect::<Vec<_>>().join(" "), p[5], "non-intersecting children of {}", p[0]);
        }
        assert_eq!(hex_ring(c).into_iter().map(to_string).collect::<Vec<_>>().join(" "), p[6], "ring of {}", p[0]);
        n += 1;
    }
    assert!(n > 500, "{n}");
}

#[test]
fn polar_cells_and_validity() {
    assert_eq!(to_string(north_polar_h3(0).unwrap()), to_string(geo_to_h3(90.0, 0.0, 0).unwrap()));
    assert!(north_polar_h3(16).is_none());
    assert!(!is_valid(0));
    assert!(is_valid(from_string("8001fffffffffff").unwrap()));
    assert_eq!(res0_cells().count(), 122);
    assert_eq!(res0_cells().filter(|c| is_pentagon(*c)).count(), 12);
}
